parameterdescription.para:
エンコードされた証明書を保存するバッファへのポインタ Example PKCS7pkcs7;
intret;

bytederBuff[]={};//initializewithDER-encodedcertificate
bytepkcs7Buff[FOURK_BUF];

wc_PKCS7_InitWithCert(&pkcs7,derBuff,sizeof(derBuff));
//updatemessageanddatatoencode
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;
pkcs7.content=data;
pkcs7.contentSz=dataSz;
...etc.

ret=wc_PKCS7_EncodeData(&pkcs7,pkcs7Buff,sizeof(pkcs7Buff));
if(ret!=0){
//errorencodingintooutputbuffer
}

エンコードされた証明書を保存するバッファへのポインタ Example PKCS7pkcs7;
intret;

bytedata[]={};//initializewithdatatosign
bytederBuff[]={};//initializewithDER-encodedcertificate
bytepkcs7Buff[FOURK_BUF];

wc_PKCS7_InitWithCert(&pkcs7,derBuff,sizeof(derBuff));
//updatemessageanddatatoencode
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;
pkcs7.content=data;
pkcs7.contentSz=dataSz;
pkcs7.hashOID=SHAh;
pkcs7.rng=&rng;
...etc.

ret=wc_PKCS7_EncodeSignedData(&pkcs7,pkcs7Buff,sizeof(pkcs7Buff));
if(ret!=0){
//errorencodingintooutputbuffer
}

wc_PKCS7_Free(&pkcs7);

エンコードされた証明書フッターを保存するバッファへのポインタ Example PKCS7pkcs7;
intret;
bytederBuff[]={};//initializewithDER-encodedcertificate
bytedata[]={};//initializewithdatatosign
bytepkcs7HeadBuff[FOURK_BUF/2];
bytepkcs7FootBuff[FOURK_BUF/2];
word32pkcs7HeadSz=(word32)sizeof(pkcs7HeadBuff);
word32pkcs7FootSz=(word32)sizeof(pkcs7HeadBuff);
enumwc_HashTypehashType=WC_HASH_TYPE_SHA;
bytehashBuf[WC_MAX_DIGEST_SIZE];
word32hashSz=wc_HashGetDigestSize(hashType);

wc_PKCS7_InitWithCert(&pkcs7,derBuff,sizeof(derBuff));
//updatemessageanddatatoencode
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;
pkcs7.content=NULL;
pkcs7.contentSz=dataSz;
pkcs7.hashOID=SHAh;
pkcs7.rng=&rng;
...etc.

//calculatehashforcontent
ret=wc_HashInit(&hash,hashType);
if(ret==0){
ret=wc_HashUpdate(&hash,hashType,data,sizeof(data));
if(ret==0){
ret=wc_HashFinal(&hash,hashType,hashBuf);
}
wc_HashFree(&hash,hashType);
}

ret=wc_PKCS7_EncodeSignedData_ex(&pkcs7,hashBuf,hashSz,pkcs7HeadBuff,
&pkcs7HeadSz,pkcs7FootBuff,&pkcs7FootSz);
if(ret!=0){
//errorencodingintooutputbuffer
}

wc_PKCS7_Free(&pkcs7);

署名されたメッセージを含むバッファへのポインタを検証および復号化する Example PKCS7pkcs7;
intret;
bytepkcs7Buff[]={};//thePKCS7signature

wc_PKCS7_InitWithCert(&pkcs7,NULL,0);
//updatemessageanddatatoencode
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;
pkcs7.content=data;
pkcs7.contentSz=dataSz;
...etc.

ret=wc_PKCS7_VerifySignedData(&pkcs7,pkcs7Buff,sizeof(pkcs7Buff));
if(ret!=0){
//errorencodingintooutputbuffer
}

wc_PKCS7_Free(&pkcs7);

署名されたメッセージフッターを含むバッファへのポインタを検証してデコードする Example PKCS7pkcs7;
intret;
bytedata[]={};//initializewithdatatosign
bytepkcs7HeadBuff[]={};//initializewithPKCS7header
bytepkcs7FootBuff[]={};//initializewithPKCS7footer
enumwc_HashTypehashType=WC_HASH_TYPE_SHA;
bytehashBuf[WC_MAX_DIGEST_SIZE];
word32hashSz=wc_HashGetDigestSize(hashType);

wc_PKCS7_InitWithCert(&pkcs7,NULL,0);
//updatemessageanddatatoencode
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;
pkcs7.content=NULL;
pkcs7.contentSz=dataSz;
pkcs7.rng=&rng;
...etc.

//calculatehashforcontent
ret=wc_HashInit(&hash,hashType);
if(ret==0){
ret=wc_HashUpdate(&hash,hashType,data,sizeof(data));
if(ret==0){
ret=wc_HashFinal(&hash,hashType,hashBuf);
}
wc_HashFree(&hash,hashType);
}

ret=wc_PKCS7_VerifySignedData_ex(&pkcs7,hashBuf,hashSz,pkcs7HeadBuff,
sizeof(pkcs7HeadBuff),pkcs7FootBuff,sizeof(pkcs7FootBuff));
if(ret!=0){
//errorencodingintooutputbuffer
}

wc_PKCS7_Free(&pkcs7);

エンコードされた証明書を保存するバッファへのポインタ Example PKCS7pkcs7;
intret;

bytederBuff[]={};//initializewithDER-encodedcertificate
bytepkcs7Buff[FOURK_BUF];

wc_PKCS7_InitWithCert(&pkcs7,derBuff,sizeof(derBuff));
//updatemessageanddatatoencode
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;
pkcs7.content=data;
pkcs7.contentSz=dataSz;
...etc.

ret=wc_PKCS7_EncodeEnvelopedData(&pkcs7,pkcs7Buff,sizeof(pkcs7Buff));
if(ret!=0){
//errorencodingintooutputbuffer
}

デコードされたメッセージを保存するバッファへのポインタ Example PKCS7pkcs7;
bytereceived[]={};//initializewithreceivedenvelopedmessage
bytedecoded[FOURK_BUF];
intdecodedSz;

//initializepkcs7withcertificate
//updatekey
pkcs7.privateKey=key;
pkcs7.privateKeySz=keySz;

decodedSz=wc_PKCS7_DecodeEnvelopedData(&pkcs7,received,
sizeof(received),decoded,sizeof(decoded));
if(decodedSz!=0){
//errordecodingmessage
}
